func (siw *ServerInterfaceWrapper) Search(c *fiber.Ctx) error {

	handler := func(c *fiber.Ctx) error {
		return siw.Handler.Search(c)
	}

	for i := len(siw.HandlerMiddlewares) - 1; i >= 0; i-- {
		m := siw.HandlerMiddlewares[i]
		next := handler
		handler = func(c *fiber.Ctx) error {
			return m(c, next)
		}
	}

	return handler(c)
}

